@implements IDisposable
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@rendermode InteractiveServer

<PageTitle>Dashboard – @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text fs-2">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger">
                    ⚠️ @AlertService.CurrentLowStockCount items below minimum level
                </span>
            }
            else
            {
                <span class="text-success">
                    ✅ All items above minimum stock levels
                </span>
            }
        </p>
        <p class="text-muted">
            <small>Auto-refreshes every 10 seconds. Last check: @_lastRefresh.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">Polling Status</div>
    <div class="card-body">
        <span class="badge bg-info">Active</span>
        Monitoring <strong>@WarehouseState.SelectedWarehouseName</strong> for low-stock items.
    </div>
</div>

@code {
    private DateTime _lastRefresh = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe starts polling if this is the first subscriber
        AlertService.Subscribe();
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private void HandleAlertChanged()
    {
        _lastRefresh = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
        // Unsubscribe stops polling if this was the last subscriber
        AlertService.Unsubscribe();
    }
}

